package net.softm.data.kata.common;

import net.softm.data.kata.WApplication;
import net.softm.data.kata.util.PackageUtil;
import net.softm.data.kata.util.Utils;

import java.util.HashMap;

public enum Package {
    SKT_MAP(1, "com.skt.tmap.ku","data:image/webp;base64,"), // TMAP(SKT)
    KAKAO_NAVI(2, "com.locnall.KimGiSa","data:image/webp;base64,"), // Kakao Navi
    NAVER_MAP(3,"com.nhn.android.nmap","data:image/webp;base64,"), // Naver Map
    KAKAO_MAP(4, "net.daum.android.map","data:image/webp;base64,"), // Kakao Map
    GOOGLE_MAP(5, "com.google.android.apps.maps","data:image/webp;base64,"), // Google Maps
    GOOGLE_MAP_GO(6, "com.google.android.apps.mapslite","data:image/webp;base64,"), // Google Maps Go
    GOOGLE_MAP_GO2(7, "com.google.android.apps.navlite","data:image/webp;base64,"),

    ONENAVI(8, "kt.navi","data:image/webp;base64,"), // ONE NAVI(KT)
    MAPPY(9, "com.mnsoft.mappyobn","data:image/webp;base64,"),
    ATLAN(10, "kr.mappers.AtlanSmart","data:image/webp;base64,"),
    WAZE(11, "com.waze","data:image/webp;base64,"),
    OSMAND(12,"net.osmand","data:image/webp;base64,"),
    OSMANDPLUS(13,"net.osmand.plus","data:image/webp;base64,"),
    SYGIC(14,"com.sygic.aura","data:image/webp;base64,"),
    MAPSME(15,"com.mapswithme.maps.pro","data:image/webp;base64,"),
    BAIDU(16,"com.baidu.BaiduMap","data:image/webp;base64,"),
    GODUCK(17,"com.autonavi.minimap","data:image/webp;base64,"),
    SKT_MAP_RED(-1, "com.skt.skaf.l001mtm091",""),
    ;

    private Integer seq;
    private String id;
    private String icon;
    private String name;
    Package(int seq,String id,String icon) {
        this.seq = seq;
        this.id = id;
        this.icon = icon;
    }
    public Integer getSeq() {
        return seq;
    }
    public String getId() {
        return id;
    }
    public String getIcon() {
        return icon;
    }

    public String getName() {
        int resourceId = WApplication.mInstance.getResources().getIdentifier("app_name_" + id,"string",WApplication.mInstance.getPackageName());
        this.name = WApplication.mInstance.getString(resourceId);
        return name;
    }

    public boolean equals(String id) {
        return this.id.equals(id);
    }
    public static HashMap<String, Object> getPakages() {
        return getPakages("");
    }
    public static HashMap<String, Object> getPakages(String key) {
        HashMap<String, Object> pkgs = new HashMap<String, Object>();
        for (Package pkg : Package.values()) {
            if ( pkg.getSeq() > 0 ) {
                if (Utils.isEmpty(key)) {
                    HashMap<String, Object> appInfo = PackageUtil.getAppInfo(pkg.getId());
                    if (Utils.isEmpty(appInfo.get("name"))) {
                        appInfo.put("icon", pkg.getIcon());
                        appInfo.put("name", pkg.getName());
                        appInfo.put("installed", false);
                    }
                    appInfo.put("seq", pkg.getSeq());
                    pkgs.put(pkg.getId(), appInfo);
                } else {
                    if (pkg.getId().equals(key)) {
                        HashMap<String, Object> appInfo = PackageUtil.getAppInfo(key);
                        if (Utils.isEmpty(appInfo.get("name"))) {
                            appInfo.put("icon", pkg.getIcon());
                            appInfo.put("name", pkg.getName());
                            appInfo.put("installed", false);
                        }
                        appInfo.put("seq", pkg.getSeq());
                        pkgs.put(pkg.getId(), appInfo);
                    }
                }
            }
        }
        return pkgs;
    }

    public static final String aa = Package.SKT_MAP.id;
    public static Package value(String id) {
        Package rtn = null;
        switch (id) {
            case "com.skt.tmap.ku":
                rtn = Package.SKT_MAP;
                break;
            case "com.skt.skaf.l001mtm091":
                rtn = Package.SKT_MAP_RED;
                break;
            case "com.google.android.apps.maps":
                rtn = Package.GOOGLE_MAP;
                break;
            case "com.google.android.apps.mapslite":
                rtn = Package.GOOGLE_MAP_GO;
                break;
            case "com.google.android.apps.navlite":
                rtn = Package.GOOGLE_MAP_GO2;
                break;
            case "com.nhn.android.nmap":
                rtn = Package.NAVER_MAP;
                break;
            case "net.daum.android.map":
                rtn = Package.KAKAO_MAP;
                break;
            case "com.locnall.KimGiSa":
                rtn = Package.KAKAO_NAVI;
                break;
            case "kt.navi":
                rtn = Package.ONENAVI;
                break;
            case "com.mnsoft.mappyobn":
                rtn = Package.MAPPY;
                break;
            case "kr.mappers.AtlanSmart":
                rtn = Package.ATLAN;
                break;
            case "com.waze":
                rtn = Package.WAZE;
                break;
            case "net.osmand":
                rtn = Package.OSMAND;
                break;
            case "net.osmand.plus":
                rtn = Package.OSMANDPLUS;
                break;
            case "com.sygic.aura":
                rtn = Package.SYGIC;
                break;
            case "com.mapswithme.maps.pro":
                rtn = Package.MAPSME;
                break;
            case "com.autonavi.minimap":
                rtn = Package.GODUCK;
                break;
            case "com.baidu.BaiduMap":
                rtn = Package.BAIDU;
            default:
                break;
        }
        return rtn;
    }
}
